Exception fatalEx = new FatalCursorException('fatal message');
System.assertEquals('System.FatalCursorException', fatalEx.getTypeName());
fatalEx.setMessage('changed fatal');
System.assertEquals('changed fatal', fatalEx.getMessage());
System.assertEquals(0, fatalEx.getInaccessibleFields().size());
System.assertEquals(0, fatalEx.getLineNumber());
System.assertEquals('', fatalEx.getStackTraceString());
System.assertEquals(fatalEx, fatalEx.initCause(new QueryException('fatal cause')));
System.assertEquals('fatal cause', fatalEx.getCause().getMessage());
